method filter_by_substring(strings: seq<string>, substring: string) returns (result: seq<string>)
    requires |strings| >= 0
    requires substring != null
    ensures forall i :: 0 <= i < |result| ==> (result[i].Contains(substring))
    ensures |result| == |{ s | s in strings && s.Contains(substring}|
{
    result := [];
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant |result| == |{ s | s in strings[0..i] && s.Contains(substring}|
    {
        if strings[i].Contains(substring) {
            result := result + [strings[i]];
        }
        i := i + 1;
    }
}
```

